script:
(function(){
  const menu = document.getElementById('setMenu');
  const searchWrap = document.getElementById('setSearchWrap');
  const searchInput = document.getElementById('setSearch');
  const pages = document.querySelectorAll('.set-page');
  const backBtn = document.getElementById('setBackBtn');
  const setTitle = document.getElementById('setTitle');
  const rows = document.querySelectorAll('.set-row[data-target]');
  const noResults = document.getElementById('setNoResults');
  const darkToggle = document.getElementById('darkModeToggle');

  darkToggle.checked = localStorage.getItem('os_theme') === 'dark';
  darkToggle.addEventListener('change', () => {
    const isDark = darkToggle.checked;
    document.body.classList.toggle('dark-mode', isDark);
    localStorage.setItem('os_theme', isDark ? 'dark' : 'light');
    SystemOS.toast(isDark ? 'Dark Mode on' : 'Dark Mode off');
  });

  document.getElementById('appsCountVal').innerText = Object.keys(SystemOS.registry).length;

  rows.forEach(row => {
    row.onclick = () => {
      menu.style.display = 'none';
      searchWrap.style.display = 'none';
      pages.forEach(p => p.style.display = 'none');
      const target = document.getElementById(row.dataset.target);
      target.style.display = 'flex';
      target.style.flexDirection = 'column';
      backBtn.classList.add('show');
      setTitle.innerText = row.querySelector('.set-row-label').innerText;
      if (row.dataset.target === 'setStorage') calcStorage();
      if (row.dataset.target === 'setApps') loadApps();
      if (row.dataset.target === 'setDisplay') renderWallpapers();
    };
  });

  backBtn.onclick = () => {
    pages.forEach(p => p.style.display = 'none');
    menu.style.display = 'block';
    searchWrap.style.display = 'flex';
    backBtn.classList.remove('show');
    setTitle.innerText = 'Settings';
  };

  searchInput.addEventListener('input', () => {
    const q = searchInput.value.trim().toLowerCase();
    let anyVisible = false;
    document.querySelectorAll('.set-row[data-label]').forEach(row => {
      const match = !q || row.dataset.label.toLowerCase().includes(q) || row.querySelector('.set-row-label').innerText.toLowerCase().includes(q);
      row.style.display = match ? 'flex' : 'none';
      if (match) anyVisible = true;
    });
    document.querySelectorAll('.set-group').forEach(g => {
      const visibleRows = g.querySelectorAll('.set-row[data-label]:not([style*="display: none"])');
      g.style.display = (q && visibleRows.length === 0) ? 'none' : '';
    });
    document.querySelectorAll('.set-group-label').forEach(l => { l.style.display = q && !anyVisible ? 'none' : ''; });
    noResults.style.display = (q && !anyVisible) ? 'block' : 'none';
  });

  function calcStorage() {
    let totalBytes = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      totalBytes += (key.length + localStorage.getItem(key).length) * 2;
    }
    const maxBytes = 5 * 1024 * 1024;
    const usedKB = (totalBytes / 1024).toFixed(2);
    const maxKB = (maxBytes / 1024).toFixed(2);
    const percent = Math.min((totalBytes / maxBytes) * 100, 100).toFixed(1);
    document.getElementById('storageBar').style.width = percent + '%';
    document.getElementById('storageBar').style.background = percent > 80 ? '#ff3b30' : '#0a84ff';
    document.getElementById('storageText').innerText = 'Used: ' + usedKB + ' KB of ~' + maxKB + ' KB (' + percent + '%)';
  }

  function loadApps() {
    const container = document.getElementById('appListContainer');
    container.innerHTML = '';
    const registry = SystemOS.registry;
    const ids = Object.keys(registry);
    if (ids.length === 0) {
      container.innerHTML = "<div class='set-empty' style='margin:20px;'>No apps installed.</div>";
      return;
    }
    ids.forEach(id => {
      const app = registry[id];
      const isSystem = id.startsWith('com.sys.');
      const row = document.createElement('div');
      row.className = 'set-row';
      row.style.cursor = isSystem ? 'default' : 'pointer';
      row.innerHTML =
        "<div class='set-row-icon' style='background:" + app.color + ";'>" + app.icon + "</div>" +
        "<div class='set-row-label'>" + app.name + "<div style='font-size:12px; color:#8e8e93; margin-top:1px;'>" + (isSystem ? 'System App' : 'User Installed') + " · v" + (app.version || '1.0') + "</div></div>" +
        (isSystem ? '' : "<span class='set-row-value' style='color:#ff3b30; font-weight:600;'>Remove</span>");
      if (!isSystem) {
        row.onclick = () => {
          SystemOS.confirm(
            'Remove "' + app.name + '"?',
            'This will delete the app and its saved data.',
            () => { SystemOS.uninstall(id); loadApps(); document.getElementById('appsCountVal').innerText = Object.keys(SystemOS.registry).length; }
          );
        };
      }
      container.appendChild(row);
    });
  }

  const wallpapers = [
    { label: 'Midnight', css: 'linear-gradient(160deg, #2c3e50, #1a2531)' },
    { label: 'Ocean', css: 'linear-gradient(160deg, #0a84ff, #1c3f66)' },
    { label: 'Sunset', css: 'linear-gradient(160deg, #ff9500, #ff3b30)' },
    { label: 'Forest', css: 'linear-gradient(160deg, #34c759, #1e5631)' },
    { label: 'Grape', css: 'linear-gradient(160deg, #af52de, #3a1c5c)' },
    { label: 'Slate', css: 'linear-gradient(160deg, #8e8e93, #2c2c2e)' }
  ];

  function renderWallpapers() {
    const grid = document.getElementById('wallpaperGrid');
    const current = localStorage.getItem('os_wallpaper') || wallpapers[0].css;
    grid.innerHTML = wallpapers.map(w =>
      "<div class='set-wallpaper-swatch" + (w.css === current ? ' selected' : '') + "' style='background:" + w.css + ";' data-css=\"" + w.css + "\" title='" + w.label + "'></div>"
    ).join('');
    grid.querySelectorAll('.set-wallpaper-swatch').forEach(sw => {
      sw.onclick = () => {
        const css = sw.dataset.css;
        document.getElementById('mobileOS').style.background = css;
        localStorage.setItem('os_wallpaper', css);
        grid.querySelectorAll('.set-wallpaper-swatch').forEach(s => s.classList.remove('selected'));
        sw.classList.add('selected');
        SystemOS.toast('Wallpaper updated');
      };
    });
  }

  document.getElementById('applyBgBtn').onclick = () => {
    const color = document.getElementById('bgColorPicker').value;
    document.getElementById('mobileOS').style.background = color;
    localStorage.setItem('os_wallpaper', color);
    SystemOS.toast('Wallpaper updated');
    renderWallpapers();
  };

  document.getElementById('exportBackupRow').onclick = () => {
    SystemOS.exportBackup();
  };

  document.getElementById('importBackupRow').onclick = () => {
    document.getElementById('backupFileInput').click();
  };

  document.getElementById('backupFileInput').addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(ev) {
      const text = ev.target.result;
      SystemOS.confirm(
        'Restore this backup?',
        'This will replace all current apps and data on this device. This cannot be undone.',
        () => SystemOS.importBackup(text),
        'Restore'
      );
    };
    reader.readAsText(file);
    e.target.value = '';
  });
})();

(function(){
  const bodyEl = document.getElementById('fmBody');
  const searchInput = document.getElementById('fmSearch');
  const sortBtn = document.getElementById('fmSortBtn');
  const refreshBtn = document.getElementById('fmRefreshBtn');
  const toastEl = document.getElementById('fmToast');
  const modalBg = document.getElementById('fmModalBg');
  const modalTitle = document.getElementById('fmModalTitle');
  const modalMsg = document.getElementById('fmModalMsg');
  const modalCancel = document.getElementById('fmModalCancel');
  const modalConfirm = document.getElementById('fmModalConfirm');
  const storageBarFill = document.getElementById('fmStorageBarFill');
  const storageText = document.getElementById('fmStorageText');

  let searchQuery = '';
  let sortModes = ['name', 'size'];
  let sortIdx = 0;
  let pendingDeleteKey = null;

  function toast(msg){
    toastEl.innerText = msg;
    toastEl.classList.add('show');
    clearTimeout(window._fmToastTimer);
    window._fmToastTimer = setTimeout(() => toastEl.classList.remove('show'), 2000);
  }

  function iconForKey(key){
    if(key === 'os_system_registry') return { icon: '⚙️', color: '#7f8c8d', label: 'System Registry' };
    if(key === 'os_theme') return { icon: '🎨', color: '#9b59b6', label: 'Theme Setting' };
    if(key === 'os_setting_bg') return { icon: '🖼️', color: '#3498db', label: 'Wallpaper Setting' };
    if(key.startsWith('os_data_com.user.notes')) return { icon: '📝', color: '#f1c40f', label: 'Notes Data' };
    if(key.startsWith('os_data_')) return { icon: '📦', color: '#16a085', label: 'App Data' };
    return { icon: '📄', color: '#34495e', label: 'File' };
  }

  function formatBytes(n){
    if(n < 1024) return n + ' B';
    if(n < 1024*1024) return (n/1024).toFixed(1) + ' KB';
    return (n/(1024*1024)).toFixed(2) + ' MB';
  }

  function getFiles(){
    const files = [];
    for(let i = 0; i < localStorage.length; i++){
      const key = localStorage.key(i);
      if(!key.startsWith('os_')) continue;
      const data = localStorage.getItem(key) || '';
      const size = new Blob([data]).size;
      const meta = iconForKey(key);
      files.push({ key, displayName: key.replace('os_', ''), size, ...meta });
    }
    return files;
  }

  function renderStorage(files){
    const totalBytes = files.reduce((sum, f) => sum + f.size * 2, 0);
    const maxBytes = 5 * 1024 * 1024;
    const percent = Math.min((totalBytes / maxBytes) * 100, 100).toFixed(1);
    storageBarFill.style.width = percent + '%';
    storageBarFill.style.background = percent > 80 ? '#e74c3c' : '#2ecc71';
    storageText.innerText = formatBytes(totalBytes) + ' used of ~5 MB (' + percent + '%)';
  }

  function render(){
    let files = getFiles();
    renderStorage(files);

    if(searchQuery){
      files = files.filter(f => f.displayName.toLowerCase().includes(searchQuery.toLowerCase()));
    }

    const mode = sortModes[sortIdx];
    sortBtn.innerText = 'Sort: ' + (mode === 'name' ? 'Name' : 'Size');
    files.sort((a, b) => mode === 'name' ? a.displayName.localeCompare(b.displayName) : b.size - a.size);

    if(files.length === 0){
      bodyEl.innerHTML = "<div class='fm-empty'><span class='big'>🗂️</span>" + (searchQuery ? 'No files match your search.' : 'Storage is empty.') + "</div>";
      return;
    }

    bodyEl.innerHTML = files.map(f =>
      "<div class='fm-card' data-key='" + f.key + "'>" +
        "<div class='fm-icon' style='background:" + f.color + ";'>" + f.icon + "</div>" +
        "<div class='fm-info'>" +
          "<div class='fm-name'>" + f.displayName + "</div>" +
          "<div class='fm-meta'>" + f.label + " · " + formatBytes(f.size) + "</div>" +
        "</div>" +
        "<button class='fm-del-btn' data-key='" + f.key + "'>🗑️</button>" +
      "</div>"
    ).join('');

    bodyEl.querySelectorAll('.fm-del-btn').forEach(btn => {
      btn.onclick = () => confirmDelete(btn.dataset.key);
    });
  }

  function confirmDelete(key){
    pendingDeleteKey = key;
    const isRegistry = key === 'os_system_registry';
    modalTitle.innerText = isRegistry ? 'Delete System Registry?' : 'Delete file?';
    modalMsg.innerText = isRegistry
      ? 'This will remove ALL installed apps from your Web OS. This cannot be undone.'
      : 'This will permanently delete "' + key.replace('os_', '') + '". This cannot be undone.';
    modalBg.classList.add('open');
  }

  modalCancel.onclick = () => { modalBg.classList.remove('open'); pendingDeleteKey = null; };
  modalConfirm.onclick = () => {
    if(pendingDeleteKey){
      localStorage.removeItem(pendingDeleteKey);
      toast('Deleted');
      render();
    }
    modalBg.classList.remove('open');
    pendingDeleteKey = null;
  };

  let searchDebounce;
  searchInput.addEventListener('input', (e) => {
    clearTimeout(searchDebounce);
    const val = e.target.value;
    searchDebounce = setTimeout(() => { searchQuery = val; render(); }, 150);
  });

  sortBtn.onclick = () => { sortIdx = (sortIdx + 1) % sortModes.length; render(); };
  refreshBtn.onclick = () => { toast('Refreshed'); render(); };

  render();
})();

(function(){
  const tabs = document.querySelectorAll('.bld-tab');
  const panels = document.querySelectorAll('.bld-panel');
  const toastEl = document.getElementById('spToast');
  const iconPreview = document.getElementById('spIconPreview');
  const idInput = document.getElementById('bldId');
  const nameInput = document.getElementById('bldName');
  const iconInput = document.getElementById('bldIcon');
  const colorInput = document.getElementById('bldColor');
  const idErr = document.getElementById('bldIdErr');
  const nameErr = document.getElementById('bldNameErr');
  const loadSelect = document.getElementById('bldLoadApp');

  for(let id in SystemOS.registry) {
    let opt = document.createElement('option');
    opt.value = id;
    opt.innerText = SystemOS.registry[id].name + ' (' + id + ')';
    loadSelect.appendChild(opt);
  }

  function toast(msg){
    toastEl.innerText = msg;
    toastEl.classList.add('show');
    clearTimeout(window._spToastTimer);
    window._spToastTimer = setTimeout(() => toastEl.classList.remove('show'), 2200);
  }

  tabs.forEach(tab => {
    tab.onclick = () => {
      tabs.forEach(t => t.classList.remove('active'));
      panels.forEach(p => p.style.display = 'none');
      tab.classList.add('active');
      document.getElementById(tab.dataset.target).style.display = 'block';
    };
  });

  function updateIconPreview(){
    const val = iconInput.value.trim();
    iconPreview.style.background = colorInput.value;
    if(val.startsWith('http') || val.startsWith('data:image')){
      iconPreview.innerHTML = '<img src="' + val + '" style="width:100%;height:100%;object-fit:cover;">';
    } else {
      iconPreview.innerText = val || '✨';
    }
  }
  iconInput.addEventListener('input', updateIconPreview);
  colorInput.addEventListener('input', updateIconPreview);
  updateIconPreview();

  loadSelect.onchange = () => {
    const id = loadSelect.value;
    if(!id) {
      idInput.value = '';
      nameInput.value = '';
      iconInput.value = '🚀';
      colorInput.value = '#6366f1';
      document.getElementById('bldHtml').value = '';
      document.getElementById('bldJs').value = '';
      refreshHtmlHighlight();
      refreshJsHighlight();
      document.getElementById('bldInstallBtn').innerHTML = '🚀 Install App';
      updateIconPreview();
      return;
    }
    const app = SystemOS.registry[id];
    idInput.value = app.id || '';
    nameInput.value = app.name || '';
    colorInput.value = app.color || '#6366f1';
    document.getElementById('bldHtml').value = app.template || '';
    document.getElementById('bldJs').value = app.script || '';
    refreshHtmlHighlight();
    refreshJsHighlight();

    let icon = app.icon || '';
    if(icon.includes('<img')) {
      const match = icon.match(/src="([^"]+)"/);
      if(match) icon = match[1];
    }
    iconInput.value = icon;
    updateIconPreview();
    validate();
    document.getElementById('bldInstallBtn').innerHTML = '🔄 Update App';
  };

  const idPattern = /^[a-z0-9]+(\.[a-z0-9]+)+$/;
  function validate(){
    let ok = true;
    const idVal = idInput.value.trim();
    if(!idPattern.test(idVal)){
      idInput.classList.add('invalid'); idErr.style.display = 'block'; ok = false;
    } else {
      idInput.classList.remove('invalid'); idErr.style.display = 'none';
    }
    if(!nameInput.value.trim()){
      nameInput.classList.add('invalid'); nameErr.style.display = 'block'; ok = false;
    } else {
      nameInput.classList.remove('invalid'); nameErr.style.display = 'none';
    }
    return ok;
  }
  idInput.addEventListener('blur', validate);
  nameInput.addEventListener('blur', validate);

  const getVal = id => document.getElementById(id).value;
  const getConfig = () => {
    let iconVal = getVal('bldIcon');
    if (iconVal.startsWith('http') || iconVal.startsWith('data:image')) {
      iconVal = '<img src="' + iconVal + '" style="width:100%; height:100%; border-radius:12px; object-fit:cover;">';
    }
    return {
      id: getVal('bldId'),
      name: getVal('bldName'),
      icon: iconVal,
      color: getVal('bldColor'),
      template: getVal('bldHtml'),
      script: getVal('bldJs')
    };
  };

  document.getElementById('spRunPreview').onclick = () => {
    const conf = getConfig();
    const frame = document.getElementById('spPreviewFrame');
    const doc = '<!doctype html><html><head><style>body{margin:0;font-family:sans-serif;height:100vh;overflow:auto;}</style></head><body>' +
      conf.template +
      '<script>try{' + conf.script + '}catch(e){document.body.innerHTML += "<div style=\'color:#ef4444;padding:12px;font-family:monospace;font-size:12px;\'>Error: " + e.message + "</div>";}<\/script>' +
      '</body></html>';
    frame.srcdoc = doc;
  };

  document.getElementById('bldInstallBtn').onclick = () => {
    if(!validate()) { toast('Fix the highlighted fields first'); return; }
    const conf = getConfig();
    const isUpdate = !!SystemOS.registry[conf.id];
    if(isUpdate && !confirm('Update existing app: ' + conf.name + '?')) return;
    SystemOS.install(conf);
    const home = document.getElementById('homeScreen');
    if(home){ home.innerHTML = ''; for(let id in SystemOS.registry){ SystemOS.renderIcon(SystemOS.registry[id]); } }
    toast(conf.name + (isUpdate ? ' updated' : ' installed') + ' successfully!');
  };

  document.getElementById('bldDownloadBtn').onclick = () => {
    if(!validate()) { toast('Fix the highlighted fields first'); return; }
    const conf = getConfig();
    const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(conf, null, 2));
    const a = document.createElement('a');
    a.href = dataStr;
    a.download = conf.name.replace(/\s+/g, '').toLowerCase() + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    toast('Exported ' + conf.name + '.json');
  };

  function escapeHtml(str){
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  const jsTokenPattern = /(?<comment>\/\/.*|\/\*[\s\S]*?\*\/)|(?<string>`(?:\\.|[^`\\])*`|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|(?<number>\b\d+\.?\d*\b)|(?<keyword>\b(?:const|let|var|function|return|if|else|for|while|new|this|typeof|class|extends|import|export|default|try|catch|finally|throw|async|await|of|in|break|continue|switch|case|null|undefined|true|false|void|delete|instanceof|yield|static|get|set|super|do|debugger)\b)|(?<curly>[{}])|(?<square>[\[\]])|(?<paren>[()])|(?<punct>[.,;:])|(?<func>[A-Za-z_$][\w$]*(?=\s*\())|(?<any>[\s\S])/g;

  function highlightJS(code){
    return code.replace(jsTokenPattern, function(match){
      const g = arguments[arguments.length - 1];
      if(g.comment !== undefined) return '<span class="tok-comment">' + escapeHtml(match) + '</span>';
      if(g.string !== undefined) return '<span class="tok-string">' + escapeHtml(match) + '</span>';
      if(g.number !== undefined) return '<span class="tok-number">' + escapeHtml(match) + '</span>';
      if(g.keyword !== undefined) return '<span class="tok-keyword">' + escapeHtml(match) + '</span>';
      if(g.curly !== undefined) return '<span class="tok-curly">' + escapeHtml(match) + '</span>';
      if(g.square !== undefined) return '<span class="tok-square">' + escapeHtml(match) + '</span>';
      if(g.paren !== undefined) return '<span class="tok-paren">' + escapeHtml(match) + '</span>';
      if(g.punct !== undefined) return '<span class="tok-punct">' + escapeHtml(match) + '</span>';
      if(g.func !== undefined) return '<span class="tok-func">' + escapeHtml(match) + '</span>';
      return escapeHtml(match);
    });
  }

  const htmlTokenPattern = /(?<comment><!--[\s\S]*?-->)|(?<tagpunct><\/?)(?<tagname>[a-zA-Z][\w-]*)|(?<attrname>[a-zA-Z_:][-\w:.]*(?=\s*=))|(?<equals>=)|(?<attrval>"[^"]*"|'[^']*')|(?<tagclose>\/?>)|(?<any>[\s\S])/g;

  function highlightHTML(code){
    return code.replace(htmlTokenPattern, function(match){
      const g = arguments[arguments.length - 1];
      if(g.comment !== undefined) return '<span class="tok-comment">' + escapeHtml(match) + '</span>';
      if(g.tagname !== undefined) return '<span class="tok-punct">' + escapeHtml(g.tagpunct) + '</span><span class="tok-tag">' + escapeHtml(g.tagname) + '</span>';
      if(g.attrname !== undefined) return '<span class="tok-attr">' + escapeHtml(match) + '</span>';
      if(g.equals !== undefined) return '<span class="tok-punct">' + escapeHtml(match) + '</span>';
      if(g.attrval !== undefined) return '<span class="tok-string">' + escapeHtml(match) + '</span>';
      if(g.tagclose !== undefined) return '<span class="tok-punct">' + escapeHtml(match) + '</span>';
      return escapeHtml(match);
    });
  }

  const bldHtmlEl = document.getElementById('bldHtml');
  const bldJsEl = document.getElementById('bldJs');
  const bldHtmlHighlightEl = document.querySelector('#bldHtmlHighlight code');
  const bldJsHighlightEl = document.querySelector('#bldJsHighlight code');

  function refreshHtmlHighlight(){ bldHtmlHighlightEl.innerHTML = highlightHTML(bldHtmlEl.value) + '\n'; }
  function refreshJsHighlight(){ bldJsHighlightEl.innerHTML = highlightJS(bldJsEl.value) + '\n'; }

  bldHtmlEl.addEventListener('input', refreshHtmlHighlight);
  bldJsEl.addEventListener('input', refreshJsHighlight);
  bldHtmlEl.addEventListener('scroll', function(){
    document.getElementById('bldHtmlHighlight').scrollTop = bldHtmlEl.scrollTop;
    document.getElementById('bldHtmlHighlight').scrollLeft = bldHtmlEl.scrollLeft;
  });
  bldJsEl.addEventListener('scroll', function(){
    document.getElementById('bldJsHighlight').scrollTop = bldJsEl.scrollTop;
    document.getElementById('bldJsHighlight').scrollLeft = bldJsEl.scrollLeft;
  });

  refreshHtmlHighlight();
  refreshJsHighlight();

})();

(function(){
  const body = document.getElementById('storeBody');
  const tabs = document.querySelectorAll('.store-tab');
  const badge = document.getElementById('updateBadge');
  const searchInput = document.getElementById('storeSearch');
  const toastEl = document.getElementById('storeToast');
  const detailEl = document.getElementById('storeDetail');

  let allCloudApps = [];
  let currentTab = 'discover';
  let searchQuery = '';
  let loadFailed = false;

  function toast(msg){
    toastEl.innerText = msg;
    toastEl.classList.add('show');
    clearTimeout(window._storeToastTimer);
    window._storeToastTimer = setTimeout(() => toastEl.classList.remove('show'), 2200);
  }

  function verParts(v){ return String(v || '1.0').split('.').map(n => parseInt(n, 10) || 0); }
  function isNewer(cloudVer, installedVer){
    const a = verParts(cloudVer), b = verParts(installedVer);
    const len = Math.max(a.length, b.length);
    for(let i = 0; i < len; i++){
      const av = a[i] || 0, bv = b[i] || 0;
      if(av > bv) return true;
      if(av < bv) return false;
    }
    return false;
  }

  function stars(rating){
    const r = Math.round(rating || 4);
    return '★★★★★☆☆☆☆☆'.slice(5 - r, 10 - r);
  }

  function matchesSearch(app){
    if(!searchQuery) return true;
    return app.name.toLowerCase().includes(searchQuery.toLowerCase());
  }

  function getInstallState(app){
    const installedApp = SystemOS.registry[app.id];
    const isInstalled = !!installedApp;
    const installedVer = installedApp ? (installedApp.version || '1.0') : '0';
    const cloudVer = app.version || '1.0';
    const hasUpdate = isInstalled && isNewer(cloudVer, installedVer);
    return { isInstalled, hasUpdate, cloudVer, installedVer };
  }

  function refreshHomeScreen(){
    const home = document.getElementById('homeScreen');
    if(!home) return;
    home.innerHTML = '';
    for(let id in SystemOS.registry){ SystemOS.renderIcon(SystemOS.registry[id]); }
  }

  function doInstall(app, btn, isUpdate){
    if(btn){
      btn.disabled = true;
      btn.className = 'store-btn installing';
      btn.innerText = isUpdate ? 'Updating…' : 'Installing…';
    }
    setTimeout(() => {
      SystemOS.install(app);
      refreshHomeScreen();
      toast((isUpdate ? 'Updated ' : 'Installed ') + app.name);
      renderList();
    }, 450);
  }

  function doUninstall(app){
    if(!confirm('Uninstall ' + app.name + '?')) return;
    delete SystemOS.registry[app.id];
    localStorage.setItem('os_system_registry', JSON.stringify(SystemOS.registry));
    localStorage.removeItem('os_data_' + app.id);
    refreshHomeScreen();
    toast('Uninstalled ' + app.name);
    closeDetail();
    renderList();
  }

  function openDetail(app){
    const state = getInstallState(app);
    let actionHtml = '';
    if(!state.isInstalled){
      actionHtml = "<button class='detail-btn' id='detailAction' style='background:#27ae60;color:#fff;'>Get</button>";
    } else if(state.hasUpdate){
      actionHtml = "<button class='detail-btn' id='detailAction' style='background:#e67e22;color:#fff;'>Update</button>";
    } else {
      actionHtml = "<button class='detail-btn' id='detailAction' style='background:#f0f1f2;color:#c0392b;'>Uninstall</button>";
    }
    detailEl.innerHTML =
      "<div class='detail-head'>" +
        "<button class='detail-close' id='detailCloseBtn'>✕</button>" +
        "<strong style='font-size:16px;'>App Details</strong>" +
      "</div>" +
      "<div class='detail-body'>" +
        "<div style='display:flex; gap:16px; align-items:center;'>" +
          "<div class='detail-icon' style='background:" + app.color + ";'>" + app.icon + "</div>" +
          "<div>" +
            "<div style='font-size:19px; font-weight:800; color:#1c1c1e;'>" + app.name + "</div>" +
            "<div style='color:#8a9299; font-size:13px; margin-top:3px;'>v" + (app.version || '1.0') + " · " + (app.category || 'Utilities') + "</div>" +
            "<div class='store-stars' style='margin-top:4px; font-size:14px;'>" + stars(app.rating) + "</div>" +
          "</div>" +
        "</div>" +
        "<p style='color:#4a4f54; font-size:14px; line-height:1.6; margin-top:20px;'>" +
          (app.description || ('Adds ' + app.name + ' to your Web OS. Tap below to get started.')) +
        "</p>" +
        actionHtml +
      "</div>";
    detailEl.classList.add('open');
    document.getElementById('detailCloseBtn').onclick = closeDetail;
    const actionBtn = document.getElementById('detailAction');
    actionBtn.onclick = () => {
      if(!state.isInstalled){ doInstall(app, null, false); closeDetail(); }
      else if(state.hasUpdate){ doInstall(app, null, true); closeDetail(); }
      else { doUninstall(app); }
    };
  }

  function closeDetail(){ detailEl.classList.remove('open'); }

  function cardHtml(app, state, showUninstall){
    let btnHtml;
    if(showUninstall){
      btnHtml = "<button class='store-btn installed' data-action='uninstall'>Remove</button>";
    } else if(!state.isInstalled){
      btnHtml = "<button class='store-btn get' data-action='install'>GET</button>";
    } else if(state.hasUpdate){
      btnHtml = "<button class='store-btn update' data-action='update'>UPDATE</button>";
    } else {
      btnHtml = "<button class='store-btn installed' disabled>Open</button>";
    }
    return "<div class='store-card' data-id='" + app.id + "'>" +
      "<div class='store-icon' style='background:" + app.color + ";'>" + app.icon + "</div>" +
      "<div class='store-info'>" +
        "<div class='store-name'>" + app.name + "</div>" +
        "<div class='store-meta'><span class='store-stars'>" + stars(app.rating) + "</span><span>v" + state.cloudVer + "</span></div>" +
      "</div>" +
      btnHtml +
    "</div>";
  }

  function renderSkeleton(){
    body.innerHTML = '';
    for(let i = 0; i < 4; i++){
      const s = document.createElement('div');
      s.className = 'skel';
      s.innerHTML = "<div class='skel-box'></div><div style='flex:1;'><div class='skel-line' style='width:55%; margin-bottom:8px;'></div><div class='skel-line' style='width:30%;'></div></div>";
      body.appendChild(s);
    }
  }

  function renderList(){
    if(loadFailed){
      body.innerHTML = "<div class='store-empty'><span class='big'>⚠️</span>Couldn't load the App Store.<br><button class='retry-btn' id='retryBtn'>Retry</button></div>";
      document.getElementById('retryBtn').onclick = fetchApps;
      return;
    }

    let updateCount = 0;
    allCloudApps.forEach(app => { if(getInstallState(app).hasUpdate) updateCount++; });
    badge.style.display = updateCount > 0 ? 'inline-block' : 'none';
    badge.innerText = updateCount;

    let list = allCloudApps.filter(matchesSearch);
    if(currentTab === 'updates'){
      list = list.filter(app => getInstallState(app).hasUpdate);
    } else if(currentTab === 'installed'){
      list = list.filter(app => getInstallState(app).isInstalled);
    }

    if(list.length === 0){
      const msg = currentTab === 'updates' ? 'All apps are up to date!'
        : currentTab === 'installed' ? "You haven't installed anything from the store yet."
        : 'No apps found.';
      const icon = currentTab === 'updates' ? '✅' : currentTab === 'installed' ? '📦' : '🔍';
      body.innerHTML = "<div class='store-empty'><span class='big'>" + icon + "</span>" + msg + "</div>";
      return;
    }

    body.innerHTML = list.map(app => cardHtml(app, getInstallState(app), currentTab === 'installed')).join('');

    body.querySelectorAll('.store-card').forEach(card => {
      const app = allCloudApps.find(a => a.id === card.dataset.id);
      card.onclick = (e) => {
        if(e.target.closest('button')) return;
        openDetail(app);
      };
      const btn = card.querySelector('button[data-action]');
      if(btn){
        btn.onclick = (e) => {
          e.stopPropagation();
          const action = btn.dataset.action;
          if(action === 'uninstall'){ doUninstall(app); }
          else { doInstall(app, btn, action === 'update'); }
        };
      }
    });
  }

  tabs.forEach(tab => {
    tab.onclick = () => {
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      currentTab = tab.dataset.tab;
      renderList();
    };
  });

  let searchDebounce;
  searchInput.addEventListener('input', (e) => {
    clearTimeout(searchDebounce);
    const val = e.target.value;
    searchDebounce = setTimeout(() => { searchQuery = val; renderList(); }, 150);
  });

  function fetchApps(){
    loadFailed = false;
    renderSkeleton();
    fetch('cloud.json')
      .then(res => { if(!res.ok) throw new Error('bad response'); return res.json(); })
      .then(apps => { allCloudApps = apps; renderList(); })
      .catch(() => { loadFailed = true; renderList(); });
  }

  fetchApps();
})();
